INSERT INTO criterion_score_levels (id, criterion_id, score, description, source_document_id, source_locator) VALUES
    (3, 1, 2, 'Содержание соответствует предмету и его задачам', 1, 'checklist.csv:5'),
    (2, 1, 1, 'Содержание частично соответствует предмету и его задачам', 1, 'checklist.csv:6'),
    (1, 1, 0, 'Содержание не соответствует предмету и его задачам', 1, 'checklist.csv:7'),
    (6, 2, 2, 'Содержание имеет понятную структуру, способствует формированию целостного представления об изучаемом предмете (подходах/концепциях/феноменах)', 1, 'checklist.csv:9'),
    (5, 2, 1, 'Отдельные аспекты предмета представлены целостно', 1, 'checklist.csv:10'),
    (4, 2, 0, 'Предмет изучения представлен фрагментарно, хаотично, случайным набором информации', 1, 'checklist.csv:11'),
    (9, 3, 2, 'Соответствует современному уровню развития науки и практики (теоретическая и эмпирическая рамка качественные)', 1, 'checklist.csv:13'),
    (8, 3, 1, 'Примеры/иллюстрации/демонстрации не являются современными', 1, 'checklist.csv:14'),
    (7, 3, 0, 'Содержание не соответствует/не отражает современный уровень развития науки и практики. Представлены устаревшие/опровергнутые концепции/подходы. Неподтвержденные концепции представлены как (научно) обоснованные', 1, 'checklist.csv:15'),
    (12, 4, 2, 'показано место темы в более общей рамке (в предмете, в межпредметном пространстве, в системе концепций/теорий/подходов)', 1, 'checklist.csv:17'),
    (11, 4, 1, 'Общая рамка показана, но упрощенно/формально, однобоко, частично', 1, 'checklist.csv:18'),
    (10, 4, 0, 'Не показано место темы в более общей рамке (в предмете, в межпредметном пространстве, в системе концепций/теорий/подходов). Не отвечает на вопросы про связь темы с общей рамкой/ошибается при ответе', 1, 'checklist.csv:19'),
    (15, 5, 2, 'Теоретическая информация «заземлена», приведенные прикладные примеры характеризуют суть предмета изучения, демонстрируют типичные моменты предмета изучения, примеры объяснены', 1, 'checklist.csv:21'),
    (14, 5, 1, 'Приведены не достаточно яркие примеры или примеры приведены, но не объяснены', 1, 'checklist.csv:22'),
    (13, 5, 0, 'Примеры не характеризуют суть предмета изучения, не демонстрируют ключевые/типичные моменты предмета изучения. Примеры не приведены, либо приведенные примеры запутывают, не отражают предмета изучения', 1, 'checklist.csv:23'),
    (18, 6, 2, 'Восприятие требует приемлемого когнитивного усилия, т.е. содержание имеет достаточный уровень сложности, но доступно для понимания', 1, 'checklist.csv:25'),
    (17, 6, 1, 'Содержание требует сверхусилия для понимания, содержание вне зоны понимания студентов/недоступно, т.е. представляет собой чрезмерная когнитивная сложность', 1, 'checklist.csv:26'),
    (16, 6, 0, 'Содержание банально, очевидно, «попсово»; не научное или отрефлексированное эмпирическое, а на уровне бытовой логики', 1, 'checklist.csv:27'),
    (21, 7, 2, 'Содержание формирует новый запрос, связанный с предметом изучения (выводит в зону ближайшего развития, приглашает думать, озадачивает)', 1, 'checklist.csv:29'),
    (20, 7, 1, 'Содержание формирует новый запрос, не связанный с предметом изучения', 1, 'checklist.csv:30'),
    (19, 7, 0, 'Содержание не формирует новый запрос', 1, 'checklist.csv:31'),
    (24, 8, 2, 'преподаватель встраивает содержание в уже имеющиеся знания студентов не формально (ясно, убедительно, очевидно)', 1, 'checklist.csv:34'),
    (23, 8, 1, 'преподаватель встраивает содержание в уже имеющиеся знания студентов формально', 1, 'checklist.csv:35'),
    (22, 8, 0, 'преподаватель не встраивает содержание в уже имеющиеся знания студентов', 1, 'checklist.csv:36'),
    (27, 9, 2, 'содержание представляет понятно и лаконично, учитывает особенности уровня развития и восприятия студентов. Логика разворачивания содержания прозрачна для студентов', 1, 'checklist.csv:38'),
    (26, 9, 1, 'часть занятия содержание понятно и логично, часть - нет', 1, 'checklist.csv:39'),
    (25, 9, 0, 'содержание «зашумлено», преподаватель провоцирует лишнюю когнитивную нагрузку: перенасыщено деталями, отступлениями, комментариями или слишком коротко/отрывочно. Логика освоения содержания недоступна.', 1, 'checklist.csv:40'),
    (30, 10, 2, 'в соответствии с уровнем готовности группы и задачами обучения использует термины, объясняет и добивается понимания сложных/новых терминов, преимущественно избегает жаргонизмов, разговорных слов', 1, 'checklist.csv:42'),
    (29, 10, 1, 'Допускает неточности в использовании терминологии. Незначительно злоупотребляет использованием жаргонизмов, разговорных слов', 1, 'checklist.csv:43'),
    (28, 10, 0, 'Использует слишком сложные для группы /новые термины, аббревиатуры без объяснения и/или использует преимущественно разговорный язык. Грубо ошибается в использовании терминологии', 1, 'checklist.csv:44'),
    (33, 11, 2, 'сложные понятия/феномены разъясняет дополнительно. Наиболее важные сведения, выводы выделяет', 1, 'checklist.csv:46'),
    (32, 11, 1, 'эпизодически/частично использует акцентирование', 1, 'checklist.csv:47'),
    (31, 11, 0, 'более и менее важное/сложное содержание не выделяет', 1, 'checklist.csv:48'),
    (36, 12, 2, 'использует приемы и инструменты схематизации, демонстрации для облегчения/усиления восприятия содержания, в том числе цифровые', 1, 'checklist.csv:50'),
    (35, 12, 1, 'использует отвлекающее визуальное сопровождение и/или недостаточное для сложного материала', 1, 'checklist.csv:51'),
    (34, 12, 0, 'визуальное сопровождение путает, формирует ошибочное представление', 1, 'checklist.csv:52'),
    (39, 13, 2, 'Темп выдачи содержания позволяет воспринимать и осмыслять сказанное (не слишком быстро, не слишком медленно)', 1, 'checklist.csv:54'),
    (38, 13, 1, 'Темп неровный, его скачки нецелесообразны (например, на более сложном материале темп повышается, а на простом снижается)', 1, 'checklist.csv:55'),
    (37, 13, 0, 'Темп выдачи содержания слишком низкий или слишком высокий', 1, 'checklist.csv:56'),
    (42, 14, 2, 'релевантны программе, сформулированы конкретно, измеримо, достижимы в рамках одного занятия', 1, 'checklist.csv:60'),
    (41, 14, 1, 'сформулированы формально', 1, 'checklist.csv:61'),
    (40, 14, 0, 'не сформулированы', 1, 'checklist.csv:62'),
    (45, 15, 2, 'уместен, служит достижению поставленных целей, корректно использован', 1, 'checklist.csv:64'),
    (44, 15, 1, 'реализован с недочетами: например, отсутствовали инструкция и пояснения для интерактивов/ не были сразу обозначены правила и процедуры совместной работы/не в полной мере служит достижению поставленных целей', 1, 'checklist.csv:65'),
    (43, 15, 0, 'Реализован с существенными ошибками, не дающими достичь запланированного результата: например вместо практических заданий прочитана лекция', 1, 'checklist.csv:66'),
    (48, 16, 2, 'говорит грамотно, внятно, четко и достаточно громко и интонировано для удобного восприятия, дает ясные инструкции, использует читаемые слайды, опрятно выглядит', 1, 'checklist.csv:68'),
    (47, 16, 1, 'создает некомфортные условия для студентов: слишком тихий или слишком громкий голос, расположение в пространстве, требующее напряжения, дает слишком длинные инструкции и т.д.', 1, 'checklist.csv:69'),
    (46, 16, 0, 'создает дискомфортные условия для студентов: отталкивающий/отвлекающий внешний вид (одежда, манера двигаться, мимика и т.д.), неподготовленная техника, противоречивые/некорректные инструкции, презентация и материалы используются номинально (чтобы было) и т.д.', 1, 'checklist.csv:70'),
    (51, 17, 2, 'Постоянно отслеживает успешность освоения материала, обращает внимание на возникающие запросы/непонимание студентов, формулирует уточняющие вопросы/вопросы на понимание, отвечает на комментарии студентов, корректирует контент/способ работы в процессе занятия при сохранении фокуса на цели', 1, 'checklist.csv:72'),
    (50, 17, 1, 'эпизодически отслеживает этапы освоения материала, реагирует на запросы студента, но при корректировке контента частично теряет фокус на изначальной цели занятия', 1, 'checklist.csv:73'),
    (49, 17, 0, 'игнорирует\не замечает возникающие запросы студентов, не вносит корректировки в контент в связи с этими запросами, полностью теряет фокус на заявленную цель, не отслеживает этапы освоения материала', 1, 'checklist.csv:74'),
    (54, 18, 2, 'Удержание внимания студентов недирективными способами (через привлечение внимания к содержанию), обеспечение активности всей аудитории', 1, 'checklist.csv:76'),
    (53, 18, 1, 'работает с активной частью аудитории, не вовлекает остальных', 1, 'checklist.csv:77'),
    (52, 18, 0, 'игнорирует аудиторию или привлекает внимание студентов только директивными способами. Аудитория пассивна: студенты занимаются своими делами, сидят в телефонах и т.д.', 1, 'checklist.csv:78'),
    (57, 19, 2, 'преподаватель формулирует проблемные/рефлексивные вопросы, направленные на активацию мыслительной деятельности студентов', 1, 'checklist.csv:80'),
    (56, 19, 1, 'Преподаватель задает вопросы, но большинство из них направлены не на активацию мыслительной деятельности, носят организационный или риторический характер или просто занимают время занятия', 1, 'checklist.csv:81'),
    (55, 19, 0, 'Проблемные/рефлексивные вопросы не формулируются, контент занятия не предполагает активацию мыслительной деятельности аудитории', 1, 'checklist.csv:82'),
    (60, 20, 2, 'преподаватель выделяет время и организует содержательный диалог. Диалог уместен и целесообразен', 1, 'checklist.csv:84'),
    (59, 20, 1, 'В диалоге используются нецелесообразные и/или неуместные вопросы', 1, 'checklist.csv:85'),
    (58, 20, 0, 'Преподаватель не выделяет время на содержательный диалог. Или диалог есть, но он формальный, не содержательный', 1, 'checklist.csv:86'),
    (63, 21, 2, 'обеспечивает контроль образовательных результатов, связывает поставленные цели с достигнутыми результатами, подчеркивает главные мысли и выводы, в конце разделов подводит итоги, выводы, резюмирует материал', 1, 'checklist.csv:88'),
    (62, 21, 1, 'итоги подводит формально', 1, 'checklist.csv:89'),
    (61, 21, 0, 'Итоги не подводит', 1, 'checklist.csv:90'),
    (66, 22, 2, 'уместно и целесообразно использует цифровые инструменты для взаимодействия со студентами', 1, 'checklist.csv:92'),
    (65, 22, 1, 'не всегда уместно и целесообразно использует цифровые инструменты Или инструменты уместны и целесообразны, но студентам не были даны инструкции, как ими пользоваться', 1, 'checklist.csv:93'),
    (64, 22, 0, 'не использует цифровые инструменты или используемые цифровые инструменты не целесообразны и неуместны, не способствуют достижению заявленных образовательных результатов', 1, 'checklist.csv:94'),
    (69, 23, 2, 'Вызывает желание участвовать в обсуждениях, задавать вопросы, пробовать, экспериментировать. Конструктивно обсуждает разные точки зрения. Проявляет уважение. Гибко и адекватно особенностям группы / отдельных студентов занимает позицию: партнерскую или инструктирующую', 1, 'checklist.csv:98'),
    (68, 23, 1, 'Выслушивает мнения, но не учитывает их в своей работе. Работает только с активными студентами. Преимущественно выбирает инструктирующую позицию', 1, 'checklist.csv:99'),
    (67, 23, 0, 'Дает оценочные негативные комментарии студентам, позволяет себе и студентам в адрес друг друга обесценивающие, неуважительные комментарии. Общается с позиции сверху, использует поучающий тон. Или демонстрирует беспомощность, заискивание и т.п. Противопоставляет свое мнение мнению студентов, спорит. Не вовлекает участников в диалог, «гасит» активность. Проявляет неуважение', 1, 'checklist.csv:100'),
    (72, 24, 2, 'Обеспечение прогресса и/или опыта успеха (субъективное переживание студентов, что произошло их продвижение в теме, достигнут успех)', 1, 'checklist.csv:102'),
    (71, 24, 1, 'Создает комфортную атмосферу общения (студентам приятно продолжать общаться с преподавателем)', 1, 'checklist.csv:103'),
    (70, 24, 0, 'Обеспечивает опыт неуспеха на большинстве этапов обучения', 1, 'checklist.csv:104'),
    (75, 25, 2, 'Вызывает личное и профессиональное доверие', 1, 'checklist.csv:106'),
    (74, 25, 1, 'Вызывает или личное, или профессиональное доверие или оставляет студентов равнодушными', 1, 'checklist.csv:107'),
    (73, 25, 0, 'Вызывает страх, скепсис, недоумение и т.п.', 1, 'checklist.csv:108'),
    (78, 26, 2, 'Поведение и слова преподавателя подтверждают и демонстрируют то, что он преподает', 1, 'checklist.csv:110'),
    (77, 26, 1, 'Поведение преподавателя не противоречит тому, что он преподает, но и не подтверждает', 1, 'checklist.csv:111'),
    (76, 26, 0, 'Поведение и слова преподавателя (комментарии за рамками объяснений теории) противоречат тому, что он преподает', 1, 'checklist.csv:112');
