    (9, 'course_program', 'Программа дисциплины', 'materials', 'Место занятия в дисциплине, темы и результаты обучения.', 0, 'application/*'),
    (10, 'learning_objectives', 'Цели и задачи занятия', 'materials', 'Заявленные цели, задачи и ожидаемые результаты.', 0, 'text/*'),
    (11, 'assignments', 'Задания и кейсы', 'materials', 'Условия заданий, инструкции, критерии ответа и эталоны.', 0, 'application/*'),
