INSERT INTO instrument_versions (id, instrument_id, version_code, version_name, lifecycle_status, model_name, prompt_version, implementation_ref, config_summary, limitations, methodology_status, source_document_id) VALUES
    (1, 1, 'eval-2024', 'Eval-2024 — исторический транскрипт-only прототип', 'historical', 'Coze bot, идентификатор не переносится', 'embedded-v1', 'Материалы/Eval-2024/class_eval/class_feedback.ipynb', 'Для каждого критерия передавались шкала 0–2 и первые 3000 символов транскрипта; выход — балл и текстовое обоснование.', 'Нет таймкодов; анализируется не полный транскрипт; при ошибке код записывал 0; валидность не подтверждена; 17 отчётов существуют, но не импортируются.', 'partial', 2),
    (2, 2, 'observed-ui-2026', 'Наблюдаемая версия визуального модуля МГПУ', 'prototype', NULL, NULL, 'Тренировки 1773–1775 и сравнительная книга', 'Наблюдаемые показатели интерфейса без доступной спецификации версии модели.', 'Операциональные определения эмоций неизвестны; эмоции и взгляд нельзя трактовать как прямую меру внимания, доверия, успеха или безопасности.', 'not_documented', 6),
    (3, 3, 'observed-ui-2026', 'Наблюдаемая версия аудиомодуля МГПУ', 'prototype', NULL, NULL, 'Тренировки 1773–1775 и сравнительная книга', 'Наблюдаемые речевые показатели и коммуникативные тактики интерфейса.', 'Единицы и методики большинства показателей не документированы; доля речи не равна качеству диалога.', 'not_documented', 6),
    (4, 4, 'checklist-2024-v1', 'Экспертный протокол по чек-листу ТюмГУ 2024', 'reference', NULL, NULL, 'Материалы/Eval-2024/class_eval/checklist.csv', 'Двойная независимая разметка по 26 критериям с доказательствами и согласованием расхождений.', 'Требуются обучение экспертов, кодбук, проверка межэкспертного согласия и предметная экспертиза для содержательных критериев.', 'documented', 1);
