INSERT INTO effects (id, study_id, code, name, hypothesis, effect_order) VALUES
    (1, 1, 'E1', 'Конструктная валидность', 'Машина находит проявление самого критерия, а не похожий технический след.', 1),
    (2, 1, 'E2', 'Точность обнаружения событий', 'Таймкоды и сегменты согласуются с независимой экспертной разметкой.', 2),
    (3, 1, 'E3', 'Согласие по итоговой оценке', 'Машинный уровень 0–2 сопоставим с экспертным референсом при явном статусе недостатка данных.', 3),
    (4, 1, 'E4', 'Добавочная ценность мультимодальности', 'Аудио, видео и материалы улучшают результат относительно готовых метрик или одного транскрипта.', 4),
    (5, 1, 'E5', 'Переносимость', 'Качество сохраняется на новых преподавателях, дисциплинах, форматах и условиях записи.', 5),
    (6, 1, 'E6', 'Калиброванная неопределённость', 'Система распознаёт границы применимости и корректно отказывается от неподтверждённых выводов.', 6),
    (7, 1, 'E7', 'Практическая полезность эксперту', 'ИИ сокращает время и повышает воспроизводимость, не ухудшая качество решения.', 7),
    (8, 1, 'E8', 'Необходимость дополнительных данных', 'Скрытые состояния и содержательные свойства не угадываются по эмоциям или поведению; новые данные дают проверяемый прирост.', 8),
    (9, 1, 'E9', 'Надёжность во времени', 'Вывод устойчив на повторных занятиях и повторных прогонах.', 9);
INSERT INTO verification_methods (id, code, name, description, metrics, procedure) VALUES
    (1, 'T1', 'Экспертная проверка доказательств', 'Эксперт принимает или отклоняет каждый доказательный фрагмент и классифицирует подмену конструкта.', 'Доля подтверждённых доказательств; типы ложных выводов', 'Слепая независимая проверка и качественный разбор ошибок.'),
    (2, 'T2', 'Сопоставление событий и таймкодов', 'Автоматические сегменты сопоставляются с экспертными событиями.', 'Precision; recall; macro-F1; temporal IoU; допуск по таймкоду', 'Расчёт отдельно по каждому критерию на независимой выборке.'),
    (3, 'T3', 'Согласие шкалы 0–2', 'Сначала проверяется согласие экспертов, затем машина сравнивается с согласованным референсом.', 'Weighted kappa; macro-F1; MAE', 'Статус недостатка данных анализируется отдельно и не кодируется нулём.'),
    (4, 'T4', 'Мультимодальная абляция', 'На одних занятиях последовательно сравниваются A1, A2, A3 и A4.', 'Разница F1/kappa; доля подтверждённых доказательств', 'Парное сравнение с кластерным bootstrap по занятиям и преподавателям.'),
    (5, 'T5', 'Holdout и анализ переносимости', 'Настройка и тест разделяются по преподавателям и занятиям.', 'Метрики качества по стратам и их доверительные интервалы', 'Отдельные срезы по формату, размеру аудитории, дисциплине и качеству записи.'),
    (6, 'T6', 'Калибровка неопределённости', 'Проверяется точность при разных порогах уверенности и качество отказов.', 'Coverage; selective accuracy; доля корректных отказов; опасные уверенные ошибки', 'Порог фиксируется после калибровки до открытия независимого теста.'),
    (7, 'T7', 'Сбалансированный crossover A0–A5', 'Эксперты оценивают сбалансированные кейсы с ИИ-подсказками и без них.', 'Время; согласие с референсом; исправления; пропуски; оценка полезности', 'Рандомизировать порядок условий и фиксировать время работы.'),
    (8, 'T8', 'Проверка границ и добавочных данных', 'Сравнивается запись-only с записью плюс материалы, диагностика или прямой опрос.', 'Прирост качества; корректные отказы; ложные выводы без прямых данных', 'Для критериев 24–25 машинный вывод без прямых студенческих данных запрещён.'),
    (9, 'T9', 'Продольная и повторная проверка', 'Сопоставляются повторные занятия и повторные прогоны одной версии.', 'Стабильность признаков, ошибок, баллов и уверенности', 'Для критерия 26 итог возможен только по нескольким наблюдениям.');
INSERT INTO effect_checks (id, effect_id, code, verification_method_id, unit_of_analysis, comparison_description, success_rule, preregistration_required) VALUES
    (1, 1, 'EC_E1', 1, 'Доказательный фрагмент по критерию', 'A2–A4 против независимого A0.', 'Порог доли подтверждённых доказательств и допустимых типов ошибок фиксируется после калибровки.', 1),
    (2, 2, 'EC_E2', 2, 'Событие или временной сегмент', 'A2–A4 против таймкодов A0.', 'Пороги macro-F1 и temporal IoU фиксируются до независимого теста.', 1),
    (3, 3, 'EC_E3', 3, 'Критерий × занятие', 'A1–A4 против согласованного A0.', 'Пороги weighted kappa, macro-F1 и MAE фиксируются после оценки межэкспертного согласия.', 1),
    (4, 4, 'EC_E4', 4, 'Критерий × занятие', 'Парная абляция A1 ↔ A2 ↔ A3 ↔ A4.', 'Добавление модальности должно давать заранее зарегистрированный положительный эффект или обоснованно не требоваться.', 1),
    (5, 5, 'EC_E5', 5, 'Преподаватель, занятие и страта', 'A1–A4 на holdout по преподавателям с A0 как референсом.', 'Качество и интервалы должны оставаться приемлемыми в ключевых стратах.', 1),
    (6, 6, 'EC_E6', 6, 'Вывод или отказ по критерию', 'A1–A4 против A0 при разных порогах уверенности.', 'Опасные уверенные ошибки ограничены, selective accuracy растёт при снижении coverage.', 1),
    (7, 7, 'EC_E7', 7, 'Эксперт × критерий × занятие', 'Сбалансированный crossover A0 ↔ A5.', 'Время сокращается без ухудшения согласия с референсом и без роста опасных пропусков.', 1),
    (8, 8, 'EC_E8', 8, 'Критерий × набор доступных данных', 'Запись-only A4 против A4 с дополнительными материалами, диагностикой и опросами.', 'Без прямых данных система корректно отказывается; добавочные данные дают измеримый и интерпретируемый прирост.', 1),
    (9, 9, 'EC_E9', 9, 'Повторное занятие или повторный прогон', 'Повторные A4 с A0 как референсом.', 'Стабильность фиксируется заранее выбранными метриками; критерий 26 оценивается только продольно.', 1);
